class Resource {
    int* data;
    size_t size;

public:
    // Move Constructor: Steal resource, zero out source
    Resource(Resource&& other) noexcept
        : data(other.data), size(other.size)
    {
        // Moved-from object (other) must be valid and destructible
        other.data = nullptr; // Critical step
        other.size = 0;       // Valid but unspecified state
    }

    // Move Assignment: Release old, steal new
    Resource& operator=(Resource&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;
            size = other.size;
            other.data = nullptr;
            other.size = 0;
        }
        return *this;
    }
};
